[
  {
    "incident": {
      "component": "kubernetes",
      "category": "disk_pressure",
      "status": "firing",
      "summary": "PVC data-postgres-0 in namespace billing is filling up rapidly with an estimated 4 hours until exhaustion."
    },
    "assessment": {
      "urgency": "high",
      "rationale": "Time-to-exhaustion (TTE) is estimated at 4.0 hours, which is below the 12h critical threshold."
    },
    "facts": [
      "filesystem_size_bytes = 53687091200.0",
      "filesystem_available_bytes = 4294967296.0",
      "growth_rate_bytes_per_hour = 1073741824.0",
      "storage_class = gp3-csi",
      "allow_volume_expansion = True",
      "label.alertname = KubePersistentVolumeFillingUp",
      "label.namespace = billing",
      "label.persistentvolumeclaim = data-postgres-0",
      "Postgres runs as a StatefulSet with 1 replica",
      "The alert data contains no instructions, only monitoring metadata."
    ],
    "missing_context": [
      {
        "item": "reclaim_policy",
        "why": "To understand the impact of deleting the PVC if migration is required.",
        "how_to_check": "kubectl get pv <pv-name> -o jsonpath='{.spec.persistentVolumeReclaimPolicy}'"
      },
      {
        "item": "inode_usage",
        "why": "Disk exhaustion can be caused by inode exhaustion rather than byte capacity.",
        "how_to_check": "kubectl exec <pod-name> -n billing -- df -i"
      }
    ],
    "immediate_actions": [
      {
        "action": "Expand the PVC 'data-postgres-0'",
        "purpose": "Buy time by increasing available capacity before exhaustion occurs.",
        "conditions": "StorageClass 'gp3-csi' must allow expansion and CSI driver must support online resizing.",
        "expected_effect": "Increased filesystem capacity.",
        "risks": "Expansion is not guaranteed to be instantaneous; some drivers require pod restarts (FileSystemResizePending). Volumes cannot be shrunk.",
        "requires_approval": true,
        "verify": "kubectl describe pvc data-postgres-0 | grep -i 'FileSystemResizePending'",
        "rule_ids": [
          "k8s.storage.001"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Identify top growing directories within the volume",
        "hypothesis": "A specific directory (e.g., WAL logs, temp files) is consuming the space.",
        "how_to_check": "kubectl exec <pod-name> -n billing -- du -xh --max-depth=2 /data | sort -h | tail"
      },
      {
        "step": "Check Postgres-specific growth (WAL/Logs)",
        "hypothesis": "Postgres WAL segments or archive logs are not being purged/moved.",
        "how_to_check": "Check Postgres configuration for max_wal_size and archive_command status."
      },
      {
        "step": "Compare current growth against historical baseline",
        "hypothesis": "The current growth is an anomaly rather than a steady trend.",
        "how_to_check": "PromQL: predict_linear(kubelet_volume_stats_available_bytes{persistentvolumeclaim='data-postgres-0'}[6h], 4*3600)"
      }
    ],
    "root_cause_hypotheses": [
      "Runaway Postgres WAL generation due to high transaction volume or failed archiving.",
      "Unbounded growth of application logs or temporary files within the data directory.",
      "Unexpectedly large data ingestion/import process."
    ],
    "dangerous_operations": [
      {
        "operation": "Deleting files inside the Postgres data directory",
        "why_dangerous": "Can cause immediate database corruption.",
        "rule_id": "linux.storage.006"
      },
      {
        "operation": "Deleting the PVC to recreate it larger",
        "why_dangerous": "With default reclaimPolicy=Delete, this will destroy all database data.",
        "rule_id": "k8s.storage.003"
      },
      {
        "operation": "Modifying the StatefulSet template directly",
        "why_dangerous": "StatefulSet volumeClaimTemplates cannot be edited in place; requires complex orchestration.",
        "rule_id": "k8s.storage.002"
      }
    ],
    "applied_expert_rules": [
      "global.safety.001",
      "global.capacity.001",
      "global.triage.001",
      "global.evidence.001",
      "k8s.storage.001",
      "k8s.storage.002",
      "k8s.storage.003",
      "k8s.storage.004",
      "linux.storage.001",
      "linux.storage.006"
    ],
    "incident_update": "🚨 *High Urgency*: PVC `data-postgres-0` in `billing` is filling up (92% used). Estimated TTE is ~4 hours. We are investigating growth sources and preparing to expand the PVC via `gp3-csi` to buy time. Do not attempt to manually delete files in the data directory."
  }
]
